public final class Level4Controller extends BaseLevelController{protected int level(){return 4;}protected String titleText(){return "LATENT HEAT OF VAPORISATION";}protected String objectiveText(){return "Cool an athlete through evaporation.";}protected String instructionText(){return "Move energy in the correct sequence from body to escaping vapour.";}protected List<String> challengeItems(){return List.of("Body heat","Sweat droplet","Evaporation","Cool skin");}protected List<Integer> correctOrder(){return List.of(0,1,2,3);}protected String quizPrompt(){return "Why does sweating cool us?";}protected List<String> quizChoices(){return List.of("Sweat is naturally cold","Evaporation absorbs heat","Sweat blocks sunlight","Water lowers density");}protected int quizCorrect(){return 1;}protected String explanation(){return "The highest-energy water molecules escape and absorb latent heat from the skin.";}}
